-- The two checklists published on 2026-11-21: When Someone Close Moves Away
-- (Goodbyes) and When You Are Always Running Late (Lateness).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-21`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-someone-close-moves-away', 'When Someone Close Moves Away', 'Open this in the weeks around a close friend or family member leaving town, when you are happy for them and quietly bereft. It helps you mark the goodbye properly and build the habits that keep a friendship alive at a distance.', 'Goodbyes', '["Say the goodbye out loud, in person — An unsaid farewell tends to sit in you for months.", "Do one ordinary thing together first — The last coffee in the usual place is worth more than a party.", "Admit you will miss them, plainly — Saying it gives them the same permission to say it back.", "Set the first call before they leave — A date on the calendar stops the first month going silent.", "Pick a standing time that suits both clocks — A regular slot survives a time difference better than good intentions.", "Send small things, not updates — A photo of their old street beats a monthly summary of your news.", "Expect week three to be the worst — The quiet arrives after the busy part of their move is over.", "Give one of their old evenings a new use — Filling the empty slot is kinder than leaving it open."]'::jsonb, 'as needed', array['Loneliness', 'Relationships', 'Life Transitions']::text[], 1, '2026-11-21T16:00:00+00:00'::timestamptz),
  ('when-you-are-always-running-late', 'When You Are Always Running Late', 'Open this if you arrive apologizing more often than not, and the rush has started to cost you sleep and goodwill. It looks at where the minutes actually go and sets up a few habits that get you there on time.', 'Lateness', '["Time the journey once, honestly — Most lateness is a travel estimate made years ago and never checked.", "Add fifteen minutes to every estimate — The buffer is the fix, and it costs less than the rush does.", "Set the alarm for leaving, not for starting — The reminder that matters is the one to put your coat on.", "Lay out keys, bag and coat the night before — The hunt for small things is where whole minutes disappear.", "Stop starting one more task before you go — The last email is the usual reason for a late arrival.", "Plan to arrive early and wait — Ten minutes with a book beats ten minutes of apologies.", "Tell people the real time you will arrive — An honest estimate protects the relationship better than hope.", "Notice which trips you are never late for — Whatever you do differently there is the habit worth copying."]'::jsonb, 'weekly', array['Habits', 'Stress', 'Work']::text[], 1, '2026-11-21T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
